func addBinary(a string, b string) string {
	i, j := len(a)-1, len(b)-1
	carry := 0
	res := []byte{}
	for i >= 0 || j >= 0 || carry > 0 {
		sum := carry
		if i >= 0 {
			sum += int(a[i] - '0')
			i--
		}
		if j >= 0 {
			sum += int(b[j] - '0')
			j--
		}
		res = append(res, byte(sum%2)+'0')
		carry = sum / 2
	}
	for l, r := 0, len(res)-1; l < r; l, r = l+1, r-1 {
		res[l], res[r] = res[r], res[l]
	}
	return string(res)
}

class Solution {
  public String addBinary(String a, String b) {
    StringBuilder sb = new StringBuilder();
    int i = a.length() - 1, j = b.length() - 1, carry = 0;
    while (i >= 0 || j >= 0 || carry > 0) {
      int sum = carry;
      if (i >= 0) {
        sum += a.charAt(i) - '0';
        i--;
      }
      if (j >= 0) {
        sum += b.charAt(j) - '0';
        j--;
      }
      sb.append(sum % 2);
      carry = sum / 2;
    }
    return sb.reverse().toString();
  }
}

class Solution:
    def addBinary(self, a: str, b: str) -> str:
        i, j, carry = len(a) - 1, len(b) - 1, 0
        res = []
        while i >= 0 or j >= 0 or carry:
            total = carry
            if i >= 0:
                total += int(a[i])
                i -= 1
            if j >= 0:
                total += int(b[j])
                j -= 1
            res.append(str(total % 2))
            carry = total // 2
        return "".join(reversed(res))

impl Solution {
  pub fn add_binary(a: String, b: String) -> String {
    let (ab, bb) = (a.as_bytes(), b.as_bytes());
    let mut i = ab.len() as i32 - 1;
    let mut j = bb.len() as i32 - 1;
    let mut carry = 0;
    let mut res: Vec<u8> = vec![];
    while i >= 0 || j >= 0 || carry > 0 {
      let mut sum = carry;
      if i >= 0 {
        sum += (ab[i as usize] - b'0') as i32;
        i -= 1;
      }
      if j >= 0 {
        sum += (bb[j as usize] - b'0') as i32;
        j -= 1;
      }
      res.push((sum % 2) as u8 + b'0');
      carry = sum / 2;
    }
    res.reverse();
    String::from_utf8(res).unwrap()
  }
}

const addBinary = (a: string, b: string): string => {
  let i = a.length - 1;
  let j = b.length - 1;
  let carry = 0;
  const res: string[] = [];
  while (i >= 0 || j >= 0 || carry > 0) {
    let sum = carry;
    if (i >= 0) sum += a.charCodeAt(i--) - 48;
    if (j >= 0) sum += b.charCodeAt(j--) - 48;
    res.push(String(sum % 2));
    carry = Math.floor(sum / 2);
  }
  return res.reverse().join('');
};

char *addBinary(char *a, char *b) {
  int len_a = strlen(a);
  int len_b = strlen(b);

  int len    = len_a > len_b ? len_a + 1 : len_b + 1;
  int length = len;

  char *res = (char *)malloc(len * (sizeof(char)));
  memset(res, '\0', len);

  int upper = 0;
  while (len_a > 0 || len_b > 0) {
    int an = len_a > 0 ? a[--len_a] - '0' : 0;
    int bn = len_b > 0 ? b[--len_b] - '0' : 0;
    if (an + bn + upper == 3) {
      res[len - 2] = 49;
      upper        = 1;
    } else if (an + bn + upper == 2) {
      res[len - 2] = 48;
      upper        = 1;
    } else if (an + bn + upper == 1) {
      res[len - 2] = 49;
      upper        = 0;
    } else if (an + bn + upper == 0) {
      res[len - 2] = 48;
      upper        = 0;
    }
    len--;
  }
  if (upper == 1) {
    res = (char *)realloc(res, (length + 1) * (sizeof(char)));
    memmove(res + 1, res, length * sizeof(char));
    res[0] = '1';
  }
  return res;
}

class Solution {
public:
  string addBinary(string a, string b) {
    int len_a = a.size();
    int len_b = b.size();

    int len = len_a > len_b ? len_a : len_b;

    string res = "";

    int upper = 0;
    while (len_a > 0 || len_b > 0) {
      int an = len_a > 0 ? a[--len_a] - '0' : 0;
      int bn = len_b > 0 ? b[--len_b] - '0' : 0;
      if (an + bn + upper == 3) {
        res = "1" + res;
        upper = 1;
      } else if (an + bn + upper == 2) {
        res = "0" + res;
        upper = 1;
      } else if (an + bn + upper == 1) {
        res = "1" + res;
        upper = 0;
      } else if (an + bn + upper == 0) {
        res = "0" + res;
        upper = 0;
      }
      len--;
    }
    if (upper == 1) {
      res = "1" + res;
    }
    return res;
  }
};
